	private static final class AuditLedger {

		private final Path path;
		private final List<AuditRow> rows;

		private AuditLedger(Path path, List<AuditRow> rows) {
			this.path = path;
			this.rows = rows;
		}

		private void persist() throws IOException {
			Path parent = path.getParent();
			if (parent != null) {
				Files.createDirectories(parent);
			}
			Path temp = Files.createTempFile(parent, path.getFileName().toString() + '.', ".tmp");
			StringBuilder csv = new StringBuilder(AUDIT_HEADER).append(System.lineSeparator());
			for (AuditRow row : rows) {
				csv.append(row.toCsv()).append(System.lineSeparator());
			}
			Files.writeString(temp, csv, StandardCharsets.UTF_8);
			try {
				Files.move(temp, path, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			} catch (AtomicMoveNotSupportedException e) {
				Files.move(temp, path, StandardCopyOption.REPLACE_EXISTING);
			}
		}
	}

	private static String csv(String value) {
		String normalized = nullToEmpty(value);
		if (normalized.indexOf(',') < 0 && normalized.indexOf('"') < 0 && normalized.indexOf('\r') < 0
				&& normalized.indexOf('\n') < 0) {
			return normalized;
		}
		return '"' + normalized.replace("\"", "\"\"") + '"';
	}
